import{c as e,Q as o,j as d,m as a}from"./chunks/framework.g_l1frA7.js";const b=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"help/troubleshooting.md","filePath":"help/troubleshooting.md","lastUpdated":null}'),r={name:"help/troubleshooting.md"};function n(i,t,s,h,c,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;Login&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>Cookie not set after login</td><td><code>FINSIGHT_COOKIE_SECURE=1</code> while on bare HTTP</td><td>Set <code>0</code> for LAN tests; <code>1</code> behind HTTPS</td></tr><tr><td>401 on every RPC</td><td>Session expired or revoked</td><td>Sign in again; check <code>docker compose logs</code> for throttling</td></tr><tr><td>Throttled for 60s</td><td>5 failures on a username</td><td>Wait; the same throttle applies to unknown usernames</td></tr><tr><td>Stuck on setup wizard</td><td>First account already exists</td><td>Navigate to <code>/api/openapi.json</code> — if it returns, the server is up and you are on the wrong <code>/data</code></td></tr></tbody></table><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Container restarts</td><td><code>docker compose logs -f finsight</code>, <code>RUST_LOG=debug</code></td></tr><tr><td>Port 8674 busy</td><td>Change <code>FINSIGHT_HOST_PORT</code> in <code>.env</code></td></tr><tr><td>Wrong data after upgrade</td><td>Did you back up the whole <code>/data</code> volume, not just one per-user file?</td></tr><tr><td>Proxy shows plain HTTP</td><td>Set <code>FINSIGHT_PUBLIC_ORIGIN=https://your.domain</code> when headers are insufficient</td></tr></tbody></table><h2 id="sync" tabindex="-1">Sync <a class="header-anchor" href="#sync" aria-label="Permalink to &quot;Sync&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>SimpleFIN sync fails</td><td>Verify access URL at the bridge; check sync run error in Accounts</td></tr><tr><td>Nothing imported</td><td>Some banks delay availability; try again in an hour</td></tr><tr><td>Duplicate transactions</td><td>Re-import dedup window; confirm transfer linking</td></tr></tbody></table><h2 id="copilot" tabindex="-1">Copilot <a class="header-anchor" href="#copilot" aria-label="Permalink to &quot;Copilot&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>No streaming / hangs</td><td>Provider key valid? Base URL reachable? <code>FINSIGHT_PUBLIC_ORIGIN</code> matches HTTPS origin?</td></tr><tr><td>Totally generic answer</td><td>Question may lack ledger scope — add “last month” or an account</td></tr><tr><td>Unconverted currency warning</td><td><code>CurrencyContext</code> listed — disambiguate currency or add a rate</td></tr></tbody></table><h2 id="csv-import" tabindex="-1">CSV import <a class="header-anchor" href="#csv-import" aria-label="Permalink to &quot;CSV import&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Wrong sign</td><td>Flip sign mapping in the import preview</td></tr><tr><td>Columns misaligned</td><td>Some banks change column order — re-map in the drawer</td></tr><tr><td>File not accepted</td><td>Check the supported parser list in <code>finsight-providers</code>; file may be in an unsupported bank variant</td></tr></tbody></table><h2 id="pwa" tabindex="-1">PWA <a class="header-anchor" href="#pwa" aria-label="Permalink to &quot;PWA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Not installable</td><td>Needs HTTPS (or <code>localhost</code>); bare <code>http://&lt;lan-ip&gt;</code> cannot install</td></tr><tr><td>Offline blank</td><td>Cache only writes in a secure context — use HTTPS</td></tr><tr><td>Push / share-target inert</td><td>Depends on service worker; see above</td></tr></tbody></table><p>Logs are the fastest path: <code>docker compose logs -f finsight</code>.</p>',14)])])}const u=e(r,[["render",n]]);export{b as __pageData,u as default};
